export default function (input) {
  const d = input.event || {};
  const status = String(d.status || '').toUpperCase();
  const approved = status === 'SUCCESS';
  const pending = status === 'PENDING' || status === 'INITIAL' || status === '';
  const naira = function (v) { const n = Number(v); return isFinite(n) ? Math.round(n * 100) / 100 : 0; };
  const method = String(d.payMethod || '').toLowerCase();
  const kinds = { bankcard: 'card purchase', balancepayment: 'OPay wallet payment', banktransfer: 'transfer to terminal', bankaccount: 'transfer to terminal', ussd: 'USSD payment', qrcode: 'QR payment' };
  let kind = kinds[method] || '';
  if (!kind && /virtual account|transfer/i.test(String(d.remark || '') + ' ' + String(d.transactionName || ''))) kind = 'transfer to terminal';
  if (!kind) kind = method ? method.replace(/_/g, ' ') : (String(d.payType || '') === 'POS' ? 'pos payment' : 'payment');
  const ms = Number(d.completedTime || d.transactionTime);
  let when = isFinite(ms) && ms > 0 ? new Date(ms) : new Date(input.received_at);
  if (isNaN(when.getTime())) when = new Date(0);
  const lagos = new Date(when.getTime() + 3600 * 1000);
  const row = {
    reference: String(d.payNo || d.orderNo || ''), terminal: String(d.sn || ''), kind: kind,
    status: status ? status.toLowerCase() : 'unknown', approved: approved, amount: naira(d.amount), fee: naira(d.fee),
    happened_at: when.toISOString(), sale_date: lagos.toISOString().slice(0, 10), customer: String(d.senderName || ''),
    narration: String(d.remark || ''), response: String(d.errorMsg || ''), event: 'opay:' + String(d.payType || d.transactionType || 'payment').toLowerCase() };
  if (d.settlementAmount !== undefined && d.settlementAmount !== null && d.settlementAmount !== '') row.settled = naira(d.settlementAmount);
  return { row: row, pending: pending, naira: row.amount };
}
